{
  "tasks": [
    {
      "type": "single",
      "claim_id": "reservoir-lithology-pore-types.c2",
      "question": "Почему при анализе вулканогенных разрезов нельзя использовать алгоритмы, настроенные исключительно на терригенные породы?",
      "options": [
        "Из-за различий в химическом составе пород",
        "Из-за наличия в вулканогенных породах сложных кавернозно-трещинных структур, нехарактерных для терригенных",
        "Из-за отсутствия в вулканогенных породах межзерновой пористости",
        "Из-за того, что вулканогенные породы всегда являются глинистыми"
      ],
      "answer": 1,
      "explanation": "Вулканогенные породы по структуре порового пространства близки к карбонатным, поэтому требуют учета трещин и каверн, которые отсутствуют в простых терригенных коллекторах."
    },
    {
      "type": "cloze",
      "claim_id": "reservoir-lithology-pore-types.c6",
      "question": "Заполните пропуск",
      "text": "Для классификации глинистых коллекторов важно учитывать характер распределения глинистого материала, который может быть {{1}}.",
      "answers": [
        [
          "рассеянным, слоистым или гнездовидным",
          "рассеянной, слоистой или гнездовидной глинистостью"
        ]
      ],
      "explanation": "Согласно тексту, глинистые коллекторы разделяют именно по этим трем типам распределения глинистого материала."
    },
    {
      "type": "order",
      "claim_id": "reservoir-lithology-pore-types.c3",
      "question": "Расставьте типы коллекторов по морфологии порового пространства в соответствии с текстом:",
      "items": [
        "Межзерновые",
        "Трещинные",
        "Кавернозно-трещинные",
        "Смешанные"
      ],
      "explanation": "Данный порядок соответствует перечислению типов коллекторов по морфологии порового пространства в тексте шага."
    }
  ],
  "card": {
    "front": "В чем главное различие между терригенными и карбонатными коллекторами с точки зрения структуры пор?",
    "back": "В терригенных преобладают межзерновые поры, а в карбонатных — сложные системы из трещин, каверн и карстовых пустот."
  }
